```html
<!doctype html>
<html lang="en">
<meta charset="utf-8">
<title>Walk Anyway</title>
<style>
  body{margin:0;background:#15212b;color:white;font:16px system-ui;
       text-align:center;padding:24px}
  canvas{width:min(960px,100%);display:block;margin:0 auto 20px;
         border-radius:8px}
  button{padding:14px 24px;font:inherit;font-weight:650;
         border:0;border-radius:8px;cursor:pointer}
  p{color:#bbcbd6}
</style>
<canvas id="film" width="1280" height="720"></canvas>
<button id="download">Download 12-second video</button>
<p id="status">12 seconds · 16:9 · silent illustrated animation</p>
<script>
const canvas=document.querySelector('canvas');
const c=canvas.getContext('2d');
const button=document.querySelector('button');
const status=document.querySelector('#status');
let recording=false, start=performance.now();

function rect(x,y,w,h,color){
  c.fillStyle=color;c.fillRect(x,y,w,h);
}
function ellipse(x,y,rx,ry,color){
  c.fillStyle=color;c.beginPath();
  c.ellipse(x,y,rx,ry,0,0,Math.PI*2);c.fill();
}
function line(x,y,X,Y,color,width=3){
  c.strokeStyle=color;c.lineWidth=width;c.lineCap='round';
  c.beginPath();c.moveTo(x,y);c.lineTo(X,Y);c.stroke();
}
function text(s,x,y,size,color){
  c.fillStyle=color;c.font=`600 ${size}px system-ui`;
  c.textAlign='center';c.fillText(s,x,y);
}
function woman(t){
  const walking=t>=9;
  const progress=Math.max(0,(t-9)/3);
  const x=walking?720+progress*190:720;
  const y=walking?570-progress*85:570;
  const scale=walking?1-progress*.22:1;
  const laugh=t>=8&&t<9;
  const bob=laugh?Math.sin((t-8)*26)*3:
            walking?Math.sin(t*12)*2:Math.sin(t*2)*1;
  c.save();c.translate(x,y+bob);c.scale(scale,scale);

  ellipse(0,6,48,10,'#18273388');
  const stride=walking?Math.sin(t*12)*12:0;
  // Yellow boots and dark leggings.
  line(-15,-66,-15+stride,-13,'#354352',15);
  line(15,-66,15-stride,-13,'#354352',15);
  rect(-25+stride,-24,21,29,'#f3c53e');
  rect(-25+stride,-7,31,12,'#f3c53e');
  rect(5-stride,-24,21,29,'#f3c53e');
  rect(5-stride,-7,31,12,'#f3c53e');

  // Same red raincoat in every beat.
  c.fillStyle='#d64042';c.beginPath();
  c.moveTo(-27,-199);c.lineTo(27,-199);
  c.lineTo(43,-62);c.quadraticCurveTo(0,-50,-43,-62);
  c.closePath();c.fill();
  const swing=walking?Math.sin(t*12)*10:0;
  line(-27,-183,-44+swing,-111,'#c9353c',18);
  line(27,-183,44-swing,-111,'#c9353c',18);
  ellipse(-44+swing,-106,7,9,'#e6b49d');
  ellipse(44-swing,-106,7,9,'#e6b49d');

  if(!walking){
    line(0,-181,0,-68,'#a82b35',2);
    for(let i=0;i<4;i++)ellipse(7,-158+i*23,2,2,'#f3a49d');
  }else{
    line(-14,-188,14,-188,'#ef6a67',3);
    line(0,-181,0,-78,'#bd3039',2);
  }
  // Silver bob; face disappears when she turns away.
  ellipse(0,-225,34,39,'#d5dce1');
  rect(-34,-227,68,37,'#d5dce1');
  if(!walking){
    ellipse(0,-220,24,29,'#e6b49d');
    c.fillStyle='#d5dce1';c.beginPath();
    c.moveTo(-32,-229);c.quadraticCurveTo(-12,-273,29,-239);
    c.lineTo(8,-240);c.lineTo(-21,-217);c.closePath();c.fill();
    if(laugh){
      line(-15,-222,-8,-224,'#384351',2);
      line(8,-224,15,-222,'#384351',2);
      ellipse(1,-207,9,7,'#733744');
      line(-4,-210,6,-210,'#fff1e6',2);
    }else{
      ellipse(-10,-222,2,2,'#384351');
      ellipse(11,-222,2,2,'#384351');
      line(-5,-207,5,-207,'#995d5d',2);
    }
  }else{
    line(-23,-235,-23,-201,'#edf1f3',2);
    line(20,-239,20,-201,'#b6c1cb',2);
  }
  c.restore();
}
function bus(t){
  if(t<4||t>=8)return;
  const x=-860+((t-4)/4)*2300;
  c.save();c.translate(x,0);
  rect(0,310,780,230,'#d5aa53');
  rect(14,324,750,111,'#344b5c');
  for(let i=0;i<7;i++)rect(28+i*104,335,90,83,'#7894a5');
  rect(0,462,780,18,'#e7cc8a');
  rect(681,330,70,198,'#344b5c');
  line(715,337,715,523,'#a4b9c3',3);
  ellipse(130,535,39,39,'#23303a');
  ellipse(650,535,39,39,'#23303a');
  ellipse(130,535,18,18,'#84939c');
  ellipse(650,535,18,18,'#84939c');
  rect(761,454,16,15,'#fff0b0');
  for(let i=0;i<13;i++){
    line(60+i*55,577,30+i*55,583,'#d9ebf466',2);
  }
  c.restore();
}
function draw(t){
  const sky=c.createLinearGradient(0,0,0,720);
  sky.addColorStop(0,'#7d94a4');sky.addColorStop(1,'#c0cbd0');
  c.fillStyle=sky;c.fillRect(0,0,1280,720);
  // Distant city.
  for(let i=0;i<12;i++){
    const h=130+(i*71)%180;
    rect(i*119-40,390-h,104,h,'#6d849277');
    for(let j=0;j<4;j++)
      rect(i*119-18+j*22,260-h/2,9,15,'#d0dbde55');
  }
  rect(0,430,1280,290,'#526671');
  rect(0,570,1280,150,'#3f535f');
  line(0,574,1280,574,'#afbbc0',4);
  for(let i=0;i<28;i++){
    const x=(i*179)%1280;
    line(x,607+(i*31)%108,x+40+(i%4)*12,
         607+(i*31)%108,'#a8c2cd33',2);
  }
  // Shelter.
  rect(290,267,334,286,'#b5d4df33');
  rect(280,254,354,16,'#354b5a');
  line(293,272,293,557,'#354b5a',8);
  line(621,272,621,557,'#354b5a',8);
  line(452,272,452,552,'#64828f',4);
  rect(325,475,235,13,'#425764');
  line(347,488,347,549,'#354b5a',6);
  line(539,488,539,549,'#354b5a',6);
  line(812,282,812,550,'#384f60',7);
  rect(786,266,52,53,'#e1ebec');
  rect(796,280,32,18,'#4b6475');
  ellipse(801,304,4,4,'#4b6475');
  ellipse(823,304,4,4,'#4b6475');

  woman(t);
  bus(t);

  // Deterministic animated rain.
  for(let i=0;i<200;i++){
    const x=((i*193.7-t*100)%1360+1360)%1360;
    const y=(i*67.3+t*510)%760;
    line(x,y,x-7,y+20,'#e3f0f055',1.3);
  }
  if(t>=9.6){
    const alpha=Math.min(1,(t-9.6)/.6);
    c.save();c.globalAlpha=alpha;
    c.shadowColor='#13232c';c.shadowBlur=14;
    text('walk anyway',640,651,62,'#ffffff');
    c.restore();
  }
}
function preview(now){
  if(!recording)draw(((now-start)/1000)%12);
  requestAnimationFrame(preview);
}
requestAnimationFrame(preview);

button.onclick=()=>{
  if(!canvas.captureStream||!window.MediaRecorder){
    status.textContent='Video export needs Chrome or Edge on desktop.';
    return;
  }
  recording=true;button.disabled=true;
  status.textContent='Rendering your video… keep this tab visible for 12 seconds.';
  draw(0);
  const stream=canvas.captureStream(30);
  const mime=['video/webm;codecs=vp9','video/webm;codecs=vp8',
              'video/webm'].find(s=>MediaRecorder.isTypeSupported(s));
  const recorder=new MediaRecorder(stream,
    mime?{mimeType:mime,videoBitsPerSecond:5000000}:{});
  const chunks=[];
  recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};
  recorder.onstop=()=>{
    stream.getTracks().forEach(track=>track.stop());
    const blob=new Blob(chunks,{type:recorder.mimeType});
    const url=URL.createObjectURL(blob);
    const a=document.createElement('a');
    a.href=url;a.download='walk-anyway.webm';a.click();
    setTimeout(()=>URL.revokeObjectURL(url),60000);
    recording=false;button.disabled=false;start=performance.now();
    status.textContent='Finished — walk-anyway.webm';
  };
  recorder.start();
  const began=performance.now();
  function frame(now){
    const t=(now-began)/1000;
    draw(Math.min(t,11.999));
    if(t<12)requestAnimationFrame(frame);
    else recorder.stop();
  }
  requestAnimationFrame(frame);
};
</script>
</html>
